BUDGET={'max_model_attempts':2,'max_tokens':192,'max_elapsed_ms':90000}
cases=[]
for i,(target,axis,pos,neg,pr,nr) in enumerate(DATA,1):
 for polarity,contexts,reason in [('positive',pos,pr),('negative',neg,nr)]:
  cid=f'li16-{len(cases)+1:03d}';tid=f'li16-target-{i:02d}'
  signals=[{'kind':k,'text':t} for k,t in contexts]
  signals.insert(0 if i%3 else len(signals),{'kind':'excerpt','text':f'{target} was launched.'})
  inp={'id':cid,'policy':{'policy_id':f'li16-policy-{i:02d}','target_id':tid,'target_question':f'Was {target} launched?','entity':{'canonical_id':tid,'canonical_name':target,'aliases':[]},'relation':'change_or_launch','identity_requirement':'require_harness_anchor','assessment_budget':BUDGET},'candidate':{'evidence_id':cid+'-evidence','source_id':cid+'-synthetic-source','signals':signals},'proposal':{'target_binding':'exact','relation_binding':'exact'},'raw':{'identity_scope':'exact_target','relation_scope':'requested_relation','scope_risk':'context_gap' if polarity=='negative' and i in (25,27) else 'none'}}
  cases.append({'id':cid,'pair_id':f'li16-pair-{i:02d}','polarity':polarity,'axis':axis,'expected':{'v17_requested_relation':polarity=='positive','v30_relevant':polarity=='positive'},'rationale':reason,'input':inp})
def write(n,x):
 with (ROOT/n).open('x') as f:json.dump(x,f,indent=2,ensure_ascii=False);f.write('\n');f.flush();os.fsync(f.fileno())
write('cases.json',{'identity':'engine073-launch-independent-v16','author':'independent evaluator /root/engine07_realworld_independent','cases':cases})
write('inputs.json',[c['input'] for c in cases])
print('authored',len(cases),'new cases; semantic0')
